package fraymus.workspace;
import org.json.*;
import java.util.*;

/** Java-derived artifact plus an independent comparison of trusted-host DOM observations. */
final class ObservationReport158 {
    static JSONObject data(JSONObject w){return new JSONObject().put("source",w.getJSONObject("observation158")).put("world",w.getJSONObject("world158")).put("browser",w.getJSONObject("browser158").getJSONObject("receipt")).put("workflowId",w.getString("id"));}
    static JSONObject build(JSONObject w){String html="""
        <!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Verified observation workspace</title>
        <style>*{box-sizing:border-box}body{margin:0;background:#0c1c23;color:#e2f1ef;font:16px/1.6 system-ui;padding:clamp(16px,3vw,32px)}main{max-width:1120px;margin:auto}h1{font-size:clamp(26px,4vw,40px);margin:8px 0}h2{font-size:21px}.eyebrow{color:#81dbc7;font-size:12px;letter-spacing:.1em}.card{padding:18px;margin:16px 0;background:#142d35;border:1px solid #385960;border-radius:14px;overflow-wrap:anywhere}.warning{border-color:#c7a668;color:#ffe1a4}.controls{display:flex;gap:24px;flex-wrap:wrap}input{max-width:65vw}select{font:inherit;background:#1c3c45;color:inherit;border:1px solid #71988f;padding:8px;border-radius:8px}svg{width:100%;height:auto;background:#0a161d;border:1px solid #4c737b;border-radius:10px}rect{fill:#6bd6ba44;stroke:#80efd0;stroke-width:2}table{border-collapse:collapse;width:100%;font-size:13px}td,th{padding:8px;white-space:nowrap;border-bottom:1px solid #385960;text-align:left}.scroll{overflow:auto}pre{white-space:pre-wrap;overflow-wrap:anywhere}.metrics{display:flex;gap:25px;flex-wrap:wrap}.metrics strong{display:block;font-size:26px}</style>
        <main><div class="eyebrow">FRAYNIX / VERIFIED OBSERVATIONS / EDITION 158</div><h1>One observation. Connected evidence.</h1><p>Recorded image estimates, their bound world and a separately checked browser reference. No hidden interpolation or physical pose conversion.</p>
        <p id="limits" class="card warning"></p><div id="metrics" class="card metrics"></div>
        <div class="controls"><label>Show <select id="filter"><option value="all">Every observation</option><option value="accepted">Image estimates</option><option value="withheld">Withheld observations</option></select></label><label>Recorded frame <input id="frame" type="range" min="0" step="1"></label></div>
        <p id="selection"></p><svg id="chart" viewBox="0 0 800 450" role="img" aria-label="Normalized image rectangle, not a physical world pose"></svg><p>Image-plane location only. A rectangle is object extent, not a confidence interval. No rectangle is drawn for a withheld observation.</p>
        <section class="card"><h2>World decision</h2><p id="world"></p><p id="decision"></p></section>
        <section class="card"><h2>Browser reference</h2><p id="browser-url"></p><ul id="browser-checks"></ul><p>This page is a separately observed reference. It does not certify the tracked object's identity or supply physical calibration.</p></section>
        <section class="card"><h2>Source and uncertainty</h2><p id="source"></p><div class="scroll"><table><thead><tr><th>Frame</th><th>Status</th><th>Segment</th><th>Left</th><th>Top</th><th>Right</th><th>Bottom</th></tr></thead><tbody id="rows"></tbody></table></div><details><summary>Retained evidence</summary><pre id="provenance"></pre></details></section></main>
        <script id="data158" type="application/json">__JSON__</script><script>
        const d=JSON.parse(document.getElementById('data158').textContent),$=id=>document.getElementById(id),c=d.source.context,rows=c.rows,n=v=>v==null?'—':Number(v).toFixed(6);
        $('limits').textContent=c.uncertainty.meaning;$('frame').max=rows.length-1;$('frame').value=0;
        for(const [label,key] of [['Image estimates','accepted'],['Withheld','withheld'],['Separate measured segments','segments']]){const e=document.createElement('div'),b=document.createElement('strong');b.textContent=c[key];e.append(b,document.createTextNode(label));$('metrics').append(e)}
        $('world').textContent='World '+d.world.nativeBinding.worldId+' / revision '+d.world.nativeBinding.expectedRevision+' / body '+d.world.bodyId+'. Native position: '+d.world.worldPosition.map(n).join(', ')+'. This is the simulation state, not a measured camera pose.';
        $('decision').textContent='Allowed: '+d.world.observationUse+'. Physical placement: '+d.world.physicalPlacement+'. '+d.world.reason;
        $('browser-url').textContent=d.browser.url;for(const check of d.browser.checks){const li=document.createElement('li');li.textContent=check.selector+': '+check.text;$('browser-checks').append(li)}
        $('source').textContent='Evidence '+d.source.evidenceId+' / dataset '+d.source.datasetId+' / run '+d.source.runId+'. '+c.clockScope;
        $('provenance').textContent=JSON.stringify(d,null,2);
        function table(){const filter=$('filter').value;$('rows').replaceChildren();for(const r of rows){if(filter==='accepted'&&!r.accepted||filter==='withheld'&&r.accepted)continue;const tr=document.createElement('tr');for(const v of [String(r.ordinal),r.status,r.segment==null?'—':String(r.segment),...Array.from({length:4},(_,i)=>n(r.box?.[i]))]){const td=document.createElement('td');td.textContent=v;tr.append(td)}$('rows').append(tr)}}
        function draw(){const r=rows[Number($('frame').value)];$('selection').textContent='Frame '+r.ordinal+' / '+r.status+' / '+(r.segment==null?'no position':'segment '+r.segment);$('chart').replaceChildren();if(r.box){const e=document.createElementNS('http://www.w3.org/2000/svg','rect'),b=r.box;for(const [k,v] of Object.entries({x:b[0]*800,y:b[1]*450,width:(b[2]-b[0])*800,height:(b[3]-b[1])*450}))e.setAttribute(k,Math.fround(v));$('chart').append(e)}}$('filter').onchange=table;$('frame').oninput=draw;table();draw();
        </script></html>
        """.replace("__JSON__",data(w).toString().replace("<","\\u003c"));
        return new JSONObject().put("title",w.getString("title")).put("files",new JSONObject().put("index.html",html).put("observation.json",data(w).toString())).put("sources",new JSONArray().put(new JSONObject().put("evidenceId",w.getJSONObject("observation158").getString("evidenceId")).put("codeSha256",ObservationTask158.code())));
    }
    static String n(double v){return String.format(Locale.ROOT,"%.6f",v);}
    static JSONArray cells(JSONObject r){var a=new JSONArray().put(""+r.getInt("ordinal")).put(r.getString("status")).put(r.isNull("segment")?"—":""+r.getInt("segment"));for(int i=0;i<4;i++)a.put(r.isNull("box")?"—":n(r.getJSONArray("box").getDouble(i)));return a;}
    static int[] indexes(JSONObject w){var rows=w.getJSONObject("observation158").getJSONObject("context").getJSONArray("rows");int missing=0;for(int i=0;i<rows.length();i++)if(!rows.getJSONObject(i).getBoolean("accepted")){missing=i;break;}return new int[]{0,rows.length()-1,rows.length()/2,missing};}
    static JSONObject audit(JSONObject w,JSONObject artifact,JSONObject actual)throws Exception{
        var errors=new JSONArray();var d=data(w);var s=d.getJSONObject("source");var c=s.getJSONObject("context");var world=d.getJSONObject("world");var browser=d.getJSONObject("browser");
        if(!actual.getString("id").equals(artifact.getString("id"))||actual.getInt("version")!=artifact.getInt("version")||!Creation.reference(artifact).similar(w.getJSONObject("report")))throw new IllegalStateException("Wrong report identity");
        String pos=String.join(", ",world.getJSONArray("worldPosition").toList().stream().map(v->n(((Number)v).doubleValue())).toList());
        var labels=new JSONObject().put("limits",ObservationTask158.LIMIT).put("world","World "+world.getJSONObject("nativeBinding").getString("worldId")+" / revision "+world.getJSONObject("nativeBinding").getInt("expectedRevision")+" / body "+world.getString("bodyId")+". Native position: "+pos+". This is the simulation state, not a measured camera pose.").put("decision","Allowed: "+world.getString("observationUse")+". Physical placement: "+world.getString("physicalPlacement")+". "+world.getString("reason")).put("browser-url",browser.getString("url")).put("source","Evidence "+s.getString("evidenceId")+" / dataset "+s.getString("datasetId")+" / run "+s.getString("runId")+". "+c.getString("clockScope"));
        if(!actual.getJSONObject("labels").similar(labels))errors.put("Visible provenance, limits or decision changed");
        var expectedBrowser=new JSONArray();for(Object raw:browser.getJSONArray("checks")){var check=(JSONObject)raw;expectedBrowser.put(check.getString("selector")+": "+check.getString("text"));}if(!actual.getJSONArray("browser").similar(expectedBrowser))errors.put("Browser reference changed");
        var summary=new JSONArray();for(String k:List.of("accepted","withheld","segments"))summary.put(""+c.getInt(k));if(!summary.similar(actual.getJSONArray("summary")))errors.put("Uncertainty counts changed");
        var filters=actual.getJSONArray("filters");if(filters.length()!=3)errors.put("Three filters required");else for(int i=0;i<3;i++){String f=List.of("all","accepted","withheld").get(i);var expected=new JSONArray();for(Object raw:c.getJSONArray("rows")){var row=(JSONObject)raw;if(f.equals("all")||row.getBoolean("accepted")==f.equals("accepted"))expected.put(cells(row));}if(!f.equals(filters.getJSONObject(i).getString("filter"))||!expected.similar(filters.getJSONObject(i).getJSONArray("rows")))errors.put("Filtered source rows differ");}
        var frames=actual.getJSONArray("frames");int[] indexes=indexes(w);if(frames.length()!=4)errors.put("Four frame controls required");else for(int i=0;i<4;i++){
            var f=frames.getJSONObject(i);var r=c.getJSONArray("rows").getJSONObject(indexes[i]);String selection="Frame "+r.getInt("ordinal")+" / "+r.getString("status")+" / "+(r.isNull("segment")?"no position":"segment "+r.getInt("segment"));
            if(f.getInt("index")!=indexes[i]||!f.getString("selection").equals(selection)||!f.getBoolean("visible"))errors.put("Frame selection or chart visibility differs");var rects=f.getJSONArray("rectangles");
            if(rects.length()!=(r.isNull("box")?0:1)){errors.put("Withheld or accepted rectangle differs");continue;}if(rects.length()==1){var b=r.getJSONArray("box");var rect=rects.getJSONObject(0);double[] expected={b.getDouble(0)*800,b.getDouble(1)*450,(b.getDouble(2)-b.getDouble(0))*800,(b.getDouble(3)-b.getDouble(1))*450};for(int j=0;j<4;j++){double v=rect.getDouble(List.of("x","y","width","height").get(j));if(!Double.isFinite(v)||Math.abs(v-(double)(float)expected[j])>1e-5)errors.put("Rendered image location changed");}if(!rect.getBoolean("visible"))errors.put("Hidden rendered rectangle");}
        }
        return new JSONObject().put("passed",errors.isEmpty()).put("errors",errors).put("artifact",Creation.reference(artifact)).put("dataSha256",WorldFrames.hash(data(w))).put("observed",WorldFrames.copy(actual));
    }
}
